package org.brightstats.stats;

import java.util.*;
import java.util.function.IntConsumer;

/** Unconstrained matched product-indicator covariance SEM with double-mean centering. */
public final class SemProductIndicators {
    private SemProductIndicators(){}
    public record Coefficient(boolean free,double value,String equality,Double lower,Double upper,double scale){
        public Coefficient{equality=equality==null?"":equality;if(!free&&!equality.isBlank())throw new IllegalArgumentException("Fixed interaction coefficients cannot also belong to a free equality group.");if(!Double.isFinite(value)||!Double.isFinite(scale)||scale<=0||lower!=null&&!Double.isFinite(lower)||upper!=null&&!Double.isFinite(upper)||lower!=null&&upper!=null&&lower>=upper||lower!=null&&value<lower||upper!=null&&value>upper)throw new IllegalArgumentException("Invalid product-indicator coefficient constraints.");}
        public static Coefficient defaults(){return new Coefficient(true,.1,"",null,null,1);}
    }
    public record Interaction(String label,int[] factors,int target,Coefficient coefficient){
        public Interaction{factors=factors.clone();Arrays.sort(factors);Objects.requireNonNull(coefficient);if(label==null||label.isBlank()||label.length()>500||factors.length<2||factors.length>3||Arrays.stream(factors).distinct().count()!=factors.length||Arrays.stream(factors).anyMatch(i->i<0||i==target)||target<0)throw new IllegalArgumentException("Use two or three distinct exogenous factors for a latent interaction.");}
        @Override public int[] factors(){return factors.clone();}
    }
    public record Specification(SemModel.Model base,int[] columns,List<Interaction> interactions,Map<Integer,List<Integer>> indicatorBlocks,List<PathProcess.Probe> probes){
        public Specification{Objects.requireNonNull(base);columns=columns.clone();interactions=List.copyOf(interactions);Map<Integer,List<Integer>> copied=new LinkedHashMap<>();if(indicatorBlocks!=null)for(var entry:indicatorBlocks.entrySet()){if(entry.getKey()<0||entry.getKey()>=base.variables().size()||entry.getValue().isEmpty()||new HashSet<>(entry.getValue()).size()!=entry.getValue().size()||entry.getValue().stream().anyMatch(i->i<0||i>=base.variables().size()))throw new IllegalArgumentException("Invalid explicit product-indicator membership.");copied.put(entry.getKey(),List.copyOf(entry.getValue()));}indicatorBlocks=Collections.unmodifiableMap(copied);probes=probes==null?List.of():List.copyOf(probes);if(probes.size()>20)throw new IllegalArgumentException("Use at most twenty centered-factor probes.");Set<Integer> factorSet=new HashSet<>();for(var interaction:interactions)for(int factor:interaction.factors())factorSet.add(factor);Set<String> probeNames=new HashSet<>();for(var probe:probes)if(!probeNames.add(probe.name())||!factorSet.containsAll(probe.values().keySet()))throw new IllegalArgumentException("Product probes must be uniquely named and refer to configured interaction factors.");if(columns.length!=base.observed().length||Arrays.stream(columns).anyMatch(i->i<0)||Arrays.stream(columns).distinct().count()!=columns.length||interactions.isEmpty()||interactions.size()>16)throw new IllegalArgumentException("Provide distinct observed bindings and 1-16 product-indicator requests.");}
        public Specification(SemModel.Model base,int[] columns,List<Interaction> interactions){this(base,columns,interactions,Map.of(),List.of());}
        public Specification(SemModel.Model base,int[] columns,List<Interaction> interactions,Map<Integer,List<Integer>> indicatorBlocks){this(base,columns,interactions,indicatorBlocks,List.of());}
        @Override public int[] columns(){return columns.clone();}
    }
    public record Product(String label,int[] factors,int variable,List<int[]> indicatorSets,int[] observedVariables,double markerLoading){
        public Product{factors=factors.clone();indicatorSets=indicatorSets.stream().map(int[]::clone).toList();observedVariables=observedVariables.clone();}@Override public int[] factors(){return factors.clone();}@Override public List<int[]> indicatorSets(){return indicatorSets.stream().map(int[]::clone).toList();}@Override public int[] observedVariables(){return observedVariables.clone();}
    }
    public record Prepared(SemModel.Model model,double[][] observations,List<Product> products,double[] sourceMeans,double[] productMeans,List<String> warnings){
        public Prepared{observations=Matrices.copy(observations);products=List.copyOf(products);sourceMeans=sourceMeans.clone();productMeans=productMeans.clone();warnings=List.copyOf(warnings);}@Override public double[][] observations(){return Matrices.copy(observations);}@Override public double[] sourceMeans(){return sourceMeans.clone();}@Override public double[] productMeans(){return productMeans.clone();}
    }
    public record Conditional(String probe,int source,int target,Map<Integer,Double> centeredFactors,double derivative){public Conditional{centeredFactors=Collections.unmodifiableMap(new LinkedHashMap<>(centeredFactors));}}
    public record Fit(Specification specification,CovarianceSem.Options options,Prepared prepared,CovarianceSem.Fit covariance,List<Conditional> conditional,List<String> warnings){public Fit{conditional=List.copyOf(conditional);warnings=List.copyOf(warnings);}}
    public record Resampled(Fit point,Bootstrap.Result inference){}
    private record Term(int[] factors,String label){Term{factors=factors.clone();}}
    private record Slot(int target,String key,Coefficient coefficient){}

    private static final class Ram {
        final List<String> names;final double[][] a,s;final double[] means;final List<SemModel.Parameter> parameters=new ArrayList<>();int serial;
        Ram(SemModel.Model base,List<String> names){this.names=names;int n=names.size();a=new double[n][n];s=new double[n][n];means=new double[n];double[][] oldA=base.directed(),oldS=base.covariance();double[] oldM=base.intercepts();for(int i=0;i<oldA.length;i++){System.arraycopy(oldA[i],0,a[i],0,oldA.length);System.arraycopy(oldS[i],0,s[i],0,oldA.length);means[i]=oldM[i];}parameters.addAll(base.parameters());}
        void put(SemModel.Kind kind,int row,int column,Coefficient coefficient,String label){if(kind==SemModel.Kind.DIRECTED)a[row][column]=coefficient.value();else if(kind==SemModel.Kind.COVARIANCE){s[row][column]=coefficient.value();s[column][row]=coefficient.value();}else means[row]=coefficient.value();if(!coefficient.free())return;var location=new SemModel.Location(kind,row,column);String name=coefficient.equality();if(name.isBlank()){boolean exists;do{name="Product "+(++serial)+": "+label;exists=false;for(var parameter:parameters)if(parameter.name().equals(name))exists=true;}while(exists);}int match=-1;for(int i=0;i<parameters.size();i++)if(parameters.get(i).name().equals(name))match=i;if(match<0){parameters.add(new SemModel.Parameter(name,List.of(location),coefficient.value(),coefficient.scale(),coefficient.lower(),coefficient.upper()));return;}var old=parameters.get(match);List<SemModel.Location> locations=new ArrayList<>(old.locations());locations.add(location);Double lower=old.lower(),upper=old.upper();if(coefficient.lower()!=null)lower=lower==null?coefficient.lower():Math.max(lower,coefficient.lower());if(coefficient.upper()!=null)upper=upper==null?coefficient.upper():Math.min(upper,coefficient.upper());parameters.set(match,new SemModel.Parameter(name,locations,old.start(),old.scale(),lower,upper));}
        SemModel.Model finish(int[] observed){if(parameters.size()>512)throw new IllegalArgumentException("Product model exceeds 512 free parameters.");return new SemModel.Model(names,observed,a,s,means,parameters);}
    }
    private static boolean free(SemModel.Model model,SemModel.Kind kind,int row,int column){return model.parameters().stream().flatMap(parameter->parameter.locations().stream()).anyMatch(location->location.kind()==kind&&(location.row()==row&&location.column()==column||kind==SemModel.Kind.COVARIANCE&&location.row()==column&&location.column()==row));}
    private static double start(SemModel.Model model,SemModel.Kind kind,int row,int column){for(var parameter:model.parameters())for(var location:parameter.locations())if(location.kind()==kind&&(location.row()==row&&location.column()==column||kind==SemModel.Kind.COVARIANCE&&location.row()==column&&location.column()==row))return parameter.start();return kind==SemModel.Kind.DIRECTED?model.directed()[row][column]:model.covariance()[row][column];}
    private static Coefficient variance(double value){double start=Math.max(1e-6,value);return new Coefficient(true,start,"",1e-8,null,Math.max(.1,start));}
    private static String key(int[] factors){return Arrays.toString(factors);}
    private static List<Integer> indicators(SemModel.Model base,int factor,Set<Integer> observed,List<Integer> declared,Set<Integer> outcomes){
        if(observed.contains(factor))return List.of(factor);List<Integer> result=new ArrayList<>();double[][] a=base.directed();int[] candidates=declared==null?base.observed():declared.stream().mapToInt(Integer::intValue).toArray();for(int indicator:candidates){boolean pure=observed.contains(indicator)&&!outcomes.contains(indicator)&&(a[indicator][factor]!=0||free(base,SemModel.Kind.DIRECTED,indicator,factor));for(int parent=0;parent<a.length;parent++)if(parent!=factor&&(a[indicator][parent]!=0||free(base,SemModel.Kind.DIRECTED,indicator,parent)))pure=false;if(!pure){if(declared!=null)throw new IllegalArgumentException("Explicit matched products require pure observed indicators without other parents: "+base.variables().get(indicator));continue;}result.add(indicator);}if(result.size()<3)throw new IllegalArgumentException("A latent product factor needs at least three pure indicators: "+base.variables().get(factor));Integer marker=result.stream().filter(i->!free(base,SemModel.Kind.DIRECTED,i,factor)&&a[i][factor]!=0).findFirst().orElseThrow(()->new IllegalArgumentException("Choose a fixed nonzero marker loading for each latent interaction factor before using matched products."));result.remove(marker);result.addFirst(marker);for(int i:result)for(int j:result)if(i!=j&&(base.covariance()[i][j]!=0||free(base,SemModel.Kind.COVARIANCE,i,j)))throw new IllegalArgumentException("Selected matched-product indicator errors must be uncorrelated within each source block.");return List.copyOf(result);
    }
    public static Prepared prepare(double[][] data,Specification specification){
        int width=Matrices.width(data,3),n=data.length;var base=specification.base();int oldSize=base.variables().size();int[] columns=specification.columns();if(Arrays.stream(columns).anyMatch(i->i>=width))throw new IllegalArgumentException("Product-indicator binding is outside the dataset.");Set<Integer> observed=new HashSet<>();Map<Integer,Integer> physical=new HashMap<>();for(int i=0;i<base.observed().length;i++){int variable=base.observed()[i];observed.add(variable);physical.put(variable,columns[i]);}Set<Integer> outcomes=new HashSet<>();for(var interaction:specification.interactions())outcomes.add(interaction.target());Map<Integer,List<Integer>> blocks=new HashMap<>();Map<String,Term> terms=new LinkedHashMap<>();List<Slot> slots=new ArrayList<>();Set<String> specified=new HashSet<>();List<String> warnings=new ArrayList<>();double[][] baseA=base.directed();
        for(var interaction:specification.interactions()){if(interaction.target()>=oldSize)throw new IllegalArgumentException("Interaction outcome is outside the RAM model.");for(int factor:interaction.factors()){if(factor>=oldSize)throw new IllegalArgumentException("Interaction factor is outside the RAM model.");for(int parent=0;parent<oldSize;parent++)if(baseA[factor][parent]!=0||free(base,SemModel.Kind.DIRECTED,factor,parent))throw new IllegalArgumentException("This product-indicator contract requires exogenous interaction factors.");blocks.computeIfAbsent(factor,unused->indicators(base,factor,observed,specification.indicatorBlocks().get(factor),outcomes));}String location=interaction.target()+":"+key(interaction.factors());if(!specified.add(location))throw new IllegalArgumentException("Duplicate interaction equation term.");terms.putIfAbsent(key(interaction.factors()),new Term(interaction.factors(),interaction.label()));slots.add(new Slot(interaction.target(),key(interaction.factors()),interaction.coefficient()));}
        Set<Integer> noisy=new HashSet<>();for(var entry:blocks.entrySet())if(!observed.contains(entry.getKey()))noisy.addAll(entry.getValue());Set<Integer> selectedSources=new HashSet<>();for(var block:blocks.values())selectedSources.addAll(block);double[][] residual=base.covariance();for(int i:selectedSources)for(int j:selectedSources)if(i<j&&(noisy.contains(i)||noisy.contains(j))&&(residual[i][j]!=0||free(base,SemModel.Kind.COVARIANCE,i,j)))throw new IllegalArgumentException("Selected source-indicator errors must be uncorrelated with other selected measurement errors or observed interaction sources.");
        for(var interaction:specification.interactions())if(interaction.factors().length==3){int[] factors=interaction.factors();for(int omitted=0;omitted<3;omitted++){int[] pair=new int[2];for(int i=0,j=0;i<3;i++)if(i!=omitted)pair[j++]=factors[i];String key=key(pair);terms.putIfAbsent(key,new Term(pair,String.join(" x ",Arrays.stream(pair).mapToObj(base.variables()::get).toList())));String location=interaction.target()+":"+key;if(specified.add(location))slots.add(new Slot(interaction.target(),key,Coefficient.defaults()));}}
        List<String> names=new ArrayList<>(base.variables());List<Product> products=new ArrayList<>();Map<String,Integer> productVariables=new HashMap<>();List<Integer> addedObserved=new ArrayList<>();List<int[]> sourceSets=new ArrayList<>();List<Integer> measurementOwners=new ArrayList<>();List<String> sourceKeys=new ArrayList<>();
        for(var entry:terms.entrySet()){Term term=entry.getValue();boolean latent=Arrays.stream(term.factors()).anyMatch(factor->!observed.contains(factor));int count=latent?Arrays.stream(term.factors()).filter(factor->!observed.contains(factor)).map(factor->blocks.get(factor).size()).min().orElseThrow():1;int variable=names.size();String name="Product: "+term.label();if(names.contains(name))throw new IllegalArgumentException("Product label collides with a RAM variable: "+name);names.add(name);productVariables.put(entry.getKey(),variable);List<int[]> sets=new ArrayList<>();List<Integer> productObserved=new ArrayList<>();double marker=1;for(int factor:term.factors())if(!observed.contains(factor))marker*=baseA[blocks.get(factor).getFirst()][factor];for(int row=0;row<count;row++){int[] set=new int[term.factors().length];for(int i=0;i<set.length;i++){var candidates=blocks.get(term.factors()[i]);set[i]=candidates.get(candidates.size()==1?0:row);}int indicator;if(latent){indicator=names.size();names.add("Product indicator "+(products.size()+1)+"."+(row+1));}else indicator=variable;addedObserved.add(indicator);productObserved.add(indicator);sets.add(set);sourceSets.add(set);measurementOwners.add(latent?variable:-1);sourceKeys.add(entry.getKey());}products.add(new Product(term.label(),term.factors(),variable,sets,productObserved.stream().mapToInt(Integer::intValue).toArray(),marker));for(int factor:term.factors())if(!observed.contains(factor)&&blocks.get(factor).size()!=count)warnings.add("Matched products use "+count+" indicators from "+base.variables().get(factor)+"; all original indicators remain in the first-order measurement model.");}
        if(names.size()>128||(long)n*(columns.length+addedObserved.size())>5000000L)throw new IllegalArgumentException("Product-indicator RAM exceeds 128 variables or five million analysis cells.");double[] sourceMeans=new double[columns.length];Map<Integer,Double> meanByVariable=new HashMap<>();for(int j=0;j<columns.length;j++){for(int row=0;row<n;row++)sourceMeans[j]+=(data[row][columns[j]]-sourceMeans[j])/(row+1);meanByVariable.put(base.observed()[j],sourceMeans[j]);}double[][] prepared=new double[n][columns.length+addedObserved.size()];for(int row=0;row<n;row++)for(int col=0;col<columns.length;col++)prepared[row][col]=data[row][columns[col]];double[] productMeans=new double[addedObserved.size()],productVariances=new double[addedObserved.size()];for(int col=0;col<sourceSets.size();col++){Matrices.interrupted();int[] sources=sourceSets.get(col);for(int row=0;row<n;row++){double value=1;for(int source:sources)value*=data[row][physical.get(source)]-meanByVariable.get(source);if(!Double.isFinite(value))throw new IllegalArgumentException("Product exceeds finite range.");prepared[row][columns.length+col]=value;productMeans[col]+=(value-productMeans[col])/(row+1);}for(int row=0;row<n;row++){prepared[row][columns.length+col]-=productMeans[col];productVariances[col]+=prepared[row][columns.length+col]*prepared[row][columns.length+col]/n;}if(!(productVariances[col]>1e-12)||!Double.isFinite(productVariances[col]))throw new IllegalArgumentException("A matched product indicator has zero or invalid variance.");}
        var ram=new Ram(base,names);int offset=0;for(var product:products){boolean latent=Arrays.stream(product.factors()).anyMatch(factor->!observed.contains(factor));double firstVariance=productVariances[offset];ram.put(SemModel.Kind.COVARIANCE,product.variable(),product.variable(),variance(latent?.5*firstVariance/(product.markerLoading()*product.markerLoading()):firstVariance),product.label()+" variance");for(int local=0;local<product.observedVariables().length;local++){int indicator=product.observedVariables()[local];if(latent){int[] sources=product.indicatorSets().get(local);double initial=1;for(int i=0;i<sources.length;i++)if(!observed.contains(product.factors()[i]))initial*=start(base,SemModel.Kind.DIRECTED,sources[i],product.factors()[i]);ram.put(SemModel.Kind.DIRECTED,indicator,product.variable(),new Coefficient(local!=0,initial,"",null,null,1),names.get(indicator)+" loading");ram.put(SemModel.Kind.COVARIANCE,indicator,indicator,variance(.5*productVariances[offset]),names.get(indicator)+" residual variance");}offset++;}}
        List<Integer> roots=new ArrayList<>();for(int variable=0;variable<oldSize;variable++){boolean root=true;for(int parent=0;parent<oldSize;parent++)if(baseA[variable][parent]!=0||free(base,SemModel.Kind.DIRECTED,variable,parent))root=false;boolean newOutcome=false;for(var slot:slots)if(slot.target()==variable)newOutcome=true;if(root&&!newOutcome)roots.add(variable);}for(int p=0;p<products.size();p++){int variable=products.get(p).variable();for(int root:roots)ram.put(SemModel.Kind.COVARIANCE,variable,root,new Coefficient(true,0,"",null,null,1),products.get(p).label()+" with "+names.get(root));for(int q=0;q<p;q++)ram.put(SemModel.Kind.COVARIANCE,variable,products.get(q).variable(),new Coefficient(true,0,"",null,null,1),products.get(p).label()+" with "+products.get(q).label());}
        // Matched products from different interactions can share a noisy indicator.
        for(int i=0;i<sourceSets.size();i++)for(int j=0;j<i;j++)if(!sourceKeys.get(i).equals(sourceKeys.get(j))&&measurementOwners.get(i)>=0&&measurementOwners.get(j)>=0){boolean shared=false;for(int a:sourceSets.get(i))for(int b:sourceSets.get(j))if(a==b){int sourceFactor=-1;for(var product:products)if(product.variable()==measurementOwners.get(i))for(int index=0;index<product.indicatorSets().getFirst().length;index++){boolean included=false;for(var set:product.indicatorSets())if(set[index]==a)included=true;if(included)sourceFactor=product.factors()[index];}if(sourceFactor>=0&&!observed.contains(sourceFactor))shared=true;}if(shared)ram.put(SemModel.Kind.COVARIANCE,addedObserved.get(i),addedObserved.get(j),new Coefficient(true,0,"",null,null,1),"Shared source-indicator product residuals");}
        for(var slot:slots)ram.put(SemModel.Kind.DIRECTED,slot.target(),productVariables.get(slot.key()),slot.coefficient(),names.get(productVariables.get(slot.key()))+" to "+names.get(slot.target()));int[] allObserved=new int[base.observed().length+addedObserved.size()];System.arraycopy(base.observed(),0,allObserved,0,base.observed().length);for(int i=0;i<addedObserved.size();i++)allObserved[base.observed().length+i]=addedObserved.get(i);warnings.add("Unconstrained matched product-indicator SEM with indicator mean centering followed by product mean centering. Fixed marker loadings define the natural product metric; selected source indicators are pure and have uncorrelated selected measurement errors.");warnings.add("Base first-order structural constraints are preserved. Three-way requests include their pairwise product paths; product-factor covariances with exogenous roots and other products are free.");warnings.add("Products are nonnormal even when their constituent indicators are normal. Gaussian ML fit statistics, likelihood criteria and ordinary information-matrix inference are reference quantities, not robust tests for this product model. Use complete-procedure case bootstrap for uncertainty.");warnings.add("The product factors represent centered interactions. First-order effects are interpreted at moderator means; latent interactions and conditional associations do not by themselves identify causal effects.");return new Prepared(ram.finish(allObserved),prepared,products,sourceMeans,productMeans,warnings);
    }
    public static Fit fit(double[][] data,Specification specification,CovarianceSem.Options options){var prepared=prepare(data,specification);var covariance=CovarianceSem.fit(prepared.observations(),prepared.model(),options);List<String> warnings=new ArrayList<>(prepared.warnings());warnings.addAll(covariance.warnings());return new Fit(specification,options,prepared,covariance,conditional(specification,prepared,covariance),warnings);}
    private static List<Conditional> conditional(Specification specification,Prepared prepared,CovarianceSem.Fit fit){List<Conditional> result=new ArrayList<>();Set<PlsSem.Edge> requested=new LinkedHashSet<>();for(var interaction:specification.interactions())for(int source:interaction.factors())requested.add(new PlsSem.Edge(source,interaction.target()));List<PathProcess.Probe> probes=specification.probes().isEmpty()?List.of(new PathProcess.Probe("At moderator means",Map.of())):specification.probes();double[][] paths=fit.directed();for(var probe:probes)for(var edge:requested){double derivative=paths[edge.target()][edge.source()];for(var product:prepared.products())if(Arrays.stream(product.factors()).anyMatch(factor->factor==edge.source())){double value=paths[edge.target()][product.variable()];for(int factor:product.factors())if(factor!=edge.source())value*=probe.values().getOrDefault(factor,0.);derivative+=value;}result.add(new Conditional(probe.name(),edge.source(),edge.target(),probe.values(),derivative));}return List.copyOf(result);}
    private static double[] estimates(Fit fit){if(!fit.covariance().converged()||!fit.covariance().identified())throw new IllegalArgumentException("Product-indicator SEM did not converge to an identified solution.");double[] parameters=fit.covariance().estimates(),values=Arrays.copyOf(parameters,parameters.length+fit.conditional().size());for(int i=0;i<fit.conditional().size();i++)values[parameters.length+i]=fit.conditional().get(i).derivative();return values;}
    public static Resampled bootstrap(double[][] data,Specification specification,CovarianceSem.Options options,Bootstrap.Options resampling,IntConsumer progress){var point=fit(data,specification,options);List<Bootstrap.Parameter> parameters=new ArrayList<>();for(int i=0;i<point.prepared().model().parameters().size();i++)parameters.add(new Bootstrap.Parameter("Product-indicator SEM parameter",-1,-1,i,point.prepared().model().parameters().get(i).name()));for(int i=0;i<point.conditional().size();i++){var effect=point.conditional().get(i);parameters.add(new Bootstrap.Parameter("Conditional centered-factor derivative",effect.source(),effect.target(),i,effect.probe()+": "+specification.base().variables().get(effect.source())+" to "+specification.base().variables().get(effect.target())));}var inference=Resampling.run(data,parameters,estimates(point),resampling,(sample,rows)->estimates(fit(sample,specification,options)),progress,"Full-procedure product-indicator SEM","Every IID case draw and jackknife recomputes all indicator means, products, product means, generated RAM starts and the complete covariance SEM fit. No fixed original products are reused; failed or unidentified fits are counted.");List<String> warnings=new ArrayList<>(inference.warnings());warnings.addAll(point.warnings());inference=new Bootstrap.Result(inference.options(),inference.method(),inference.randomGenerator(),inference.signHandling(),inference.successful(),inference.failed(),inference.failures(),inference.estimates(),warnings,inference.estimator());return new Resampled(point,inference);}
}
